  integer(options.maxFileBytes, 1, MAX_FILE_BYTES, 'BASEROW_CAPTURE_ATTACHMENTS_INVALID');
  integer(options.maxFiles, 1, 10000, 'BASEROW_CAPTURE_ATTACHMENTS_INVALID');
