      only(hop, ['from', 'to', 'status', 'receivedAt', 'headers'], 'BASEROW_ATTACHMENT_REDIRECT_INVALID');
      if (hop.from !== current || ![301, 302, 303, 307, 308].includes(hop.status) ||
