        throw fault('WORKBOOK_NATIVE_REVIEW_REQUIRED','Review the actual current public schema and revision.');
      const normalized={...copy(input),name:label(input.name,160,true),notes:label(input.notes,2000)};
      // Comparison adoption is a new original mapping, with its recovery identity
      // inside this same state transaction. A lost reply must not create a second plan.
      if(migration!==undefined){
        const keys=['comparisonId','comparisonSha256','inputSha256','baselineSourceId','baselinePlanId','baselinePlanRevision'];
        if(!migration||typeof migration!=='object'||Array.isArray(migration)||
          Object.keys(migration).length!==keys.length||keys.some(key=>!(key in migration))||planId!==null||
          !UUID.test(migration.comparisonId??'')||!HASH.test(migration.comparisonSha256??'')||
          !HASH.test(migration.inputSha256??'')||!UUID.test(migration.baselineSourceId??'')||
          !UUID.test(migration.baselinePlanId??'')||!Number.isSafeInteger(migration.baselinePlanRevision)||migration.baselinePlanRevision<1)
          throw fault('INVALID_WORKBOOK_MIGRATION','Use the exact retained comparison as this mapping’s origin.');
        for(const current of row.plans)for(const edition of [current,...(current.editions??[])]){
          if(edition.migration?.comparisonId!==migration.comparisonId)continue;
          if(identity(edition.migration)!==identity(migration)||identity(edition.plan)!==identity(normalized)||
            edition.configHash!==configHash||identity(edition.config)!==identity(config)||
            edition.expectedSnapshot!==expectedSnapshot||edition.expectedRevision!==expectedRevision||
            edition.planSha256!==identity({plan:edition.plan,configHash,expectedSnapshot,expectedRevision}))
            throw fault('WORKBOOK_COMPARISON_APPLY_CONFLICT','This comparison already belongs to another retained mapping operation.',409);
          return {source:row,plan:copy(Object.fromEntries(Object.entries(edition).filter(([key])=>key!=='editions'))),
            reused:true,currentPlanRevision:current.revision};
        }
      }
      if(!Number.isSafeInteger(expectedSourceRevision)||row.revision!==expectedSourceRevision)
        throw fault('WORKBOOK_REVIEW_CHANGED','Another action changed this workbook’s saved mappings. Refresh before saving.',409);
      let prior;
      if(planId!==null){
        if(!UUID.test(planId??''))throw fault('WORKBOOK_PLAN_NOT_FOUND');
        prior=plan(id,planId,expectedPlanRevision);
      }else if(expectedPlanRevision!==null)throw fault('WORKBOOK_PLAN_CHANGED');
      if(!prior&&row.plans.length>=128)throw fault('WORKBOOK_PLAN_CAPACITY','Keep up to 128 distinct mappings per workbook.');
      const current={id:prior?.id??randomUUID(),revision:(prior?.revision??0)+1,createdAt:prior?.createdAt??stamp(),
        updatedAt:stamp(),plan:normalized,config:copy(config),configHash,expectedSnapshot,expectedRevision};
      if(migration!==undefined)current.migration=copy(migration);
      current.planSha256=identity({plan:current.plan,configHash,expectedSnapshot,expectedRevision});
      const editions=prior?[...(prior.editions??[]),Object.fromEntries(Object.entries(prior).filter(([k])=>k!=='editions'))]:[];
      if(editions.length>=256)throw fault('WORKBOOK_PLAN_CAPACITY','This mapping has 256 retained editions; create a separately named mapping for continued work.');
      current.editions=editions;
      await save(next=>{
        const position=next.workbookSources.findIndex(x=>x.id===id),item=next.workbookSources[position];
        item.revision++;item.updatedAt=stamp();
        const old=item.plans.findIndex(x=>x.id===current.id);
        if(old<0)item.plans.push(current);else item.plans[old]=current;
      });
      return {source:source(id),plan:plan(id,current.id)};
    },
    async retainParser(content){
      const sha256=digest(content),path=join(roots.parsers,sha256+'.py');
      if(await absent(path)){await createFile(path,content);await chmod(path,0o400);await syncDirectory(roots.parsers);}
      const retained=await readPrivate(path,256*1024);
      if(digest(retained)!==sha256)throw fault('WORKBOOK_PARSER_CHANGED','The retained parser source differs from its identity.',409);
      return {sha256,path,bytes:retained.length};
    },
    async parser(sha256){
      if(!HASH.test(sha256??''))throw fault('WORKBOOK_PARSER_CHANGED');
      const path=join(roots.parsers,sha256+'.py'),content=await readPrivate(path,256*1024);
      if(digest(content)!==sha256)throw fault('WORKBOOK_PARSER_CHANGED');
      return {sha256,path,bytes:content.length};
    },
    async remove(id,expectedSourceRevision){
      const row=source(id);
      if(row.revision!==expectedSourceRevision)throw fault('WORKBOOK_REVIEW_CHANGED','Refresh the saved workbook before removing it.',409);
      if(getState().candidates.some(x=>x.workbookSource?.sourceId===id))
        throw fault('WORKBOOK_IN_USE','A retained candidate still uses this original workbook. Export and explicitly remove that candidate first.',409);
      await save(next=>{next.workbookSources=next.workbookSources.filter(x=>x.id!==id);next.removedWorkbookIds.push(id);});
      await rm(paths(id).directory,{recursive:true,force:true});await syncDirectory(roots.sources);
    },
  };
}

// MIT. Retained CSV work only; the original dataset service owns publication.
import { mkdir, readdir, rename, rm, lstat, chmod } from 'node:fs/promises';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { acquireWorkspace, privateDirectory, readPrivate, readJson, createFile,
  atomicJson, syncDirectory, bytes, digest, hashPrivate, fault } from '../postgres/publisher/files.mjs';

import { openWorkbookSources, validateWorkbookOrigin } from './workbook/store.mjs';

const SCHEMA = 'stellar-forge.dataset-publisher-workspace.v1';
const CANDIDATE = 'stellar-forge.dataset-publisher-candidate.v1';
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const HASH = /^[a-f0-9]{64}$/;
const stamp = () => new Date().toISOString();
const copy = value => structuredClone(value);
const pending = record => ['PENDING', 'NEEDS_REVIEW'].includes(record.publications.at(-1)?.state);
const label = (value, maximum, required = false) => {
  if (typeof value !== 'string' || value.length > maximum || /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(value) || required && !value.trim())
    throw fault('INVALID_REVIEW_TEXT', `Enter ${required ? 'a name' : 'notes'} within ${maximum} characters.`);
  return value.trim();
};
const absent = async path => { try { await lstat(path); return false; } catch (error) { if (error.code === 'ENOENT') return true; throw error; } };

function validateCandidate(record) {
  if (record?.schema !== CANDIDATE || !UUID.test(record.id ?? '') || !HASH.test(record.csvHash ?? '') ||
      !HASH.test(record.configHash ?? '') || !HASH.test(record.dataset?.snapshot ?? '') ||
      !Number.isSafeInteger(record.sourceBytes) || record.sourceBytes < 1 || record.sourceBytes > 256 * 1024 ** 2 ||
      !Number.isSafeInteger(record.revision) || record.revision < 1 || !Array.isArray(record.publications) ||
      !HASH.test(record.expectedSnapshot ?? '') || !Number.isSafeInteger(record.expectedRevision) || record.expectedRevision < 1)
    throw fault('SAVED_CANDIDATE_INVALID', 'The retained candidate metadata is invalid. Preserve its directory for repair.');
  label(record.name, 160, true); label(record.notes, 2000);
  validateWorkbookOrigin(record.workbookSource);
  if (record.additionalSourceBytes !== undefined && (!Number.isSafeInteger(record.additionalSourceBytes) || record.additionalSourceBytes < 0 || record.additionalSourceBytes !== record.workbookSource?.rowMapBytes))
    throw fault('SAVED_WORKBOOK_ORIGIN_INVALID');
  return record;
}

function validateBuyer(record) {
  if (!UUID.test(record?.id ?? '') || !HASH.test(record.snapshot ?? '') || !HASH.test(record.configSha256 ?? '') ||
      !HASH.test(record.offerSha256 ?? '') || typeof record.intentId !== 'string' || record.intentId.length > 128 ||
      typeof record.query !== 'string' || record.query.length > 8192 || typeof record.createdAt !== 'string')
    throw fault('SAVED_BUYER_INVALID', 'The saved buyer metadata needs repair.');
  return record;
}

/** Uses the existing kernel-owned publisher lock and private atomic files.
 * No second seller/version store is opened, including during crash recovery. */
export async function openPublisherDrafts({ datasetDirectory, directory = join(datasetDirectory, '.publisher-workspace'),
  maxCandidates = 32, maxSourceBytes = 256 * 1024 * 1024 } = {}) {
  if (!Number.isSafeInteger(maxCandidates) || maxCandidates < 1 || maxCandidates > 256 ||
      !Number.isSafeInteger(maxSourceBytes) || maxSourceBytes < 1024 || maxSourceBytes > 4 * 1024 ** 3)
    throw fault('INVALID_DRAFT_CAPACITY', 'Choose 1–256 candidates and 1 KiB–4 GiB of retained CSV capacity.');
  if (directory === datasetDirectory || datasetDirectory.startsWith(directory + '/') ||
      directory.startsWith(join(datasetDirectory, 'versions') + '/') || directory === join(datasetDirectory, 'versions'))
    throw fault('SEPARATE_WORKSPACE_REQUIRED', 'Keep draft work outside the original published-version directories.');
  await privateDirectory(directory, true);
  const unlock = await acquireWorkspace(directory);
  let state, closed = false;
  const recoveryWarnings = [];
  const roots = { candidates: join(directory, 'candidates'), staging: join(directory, 'staging'), buyers: join(directory, 'buyers') };
  const indexPath = join(directory, 'workspace.json');
  try {
    if (await absent(indexPath)) {
      const existing = await readdir(directory);
      if (existing.some(name => name !== 'publisher.lock' && !(name.startsWith('.pending-') && UUID.test(name.slice(9)))))
        throw fault('WORKSPACE_METADATA_MISSING', 'This directory contains existing files without its workspace metadata. Use its original workspace or a new directory.');
      for (const name of existing) if (name.startsWith('.pending-') && UUID.test(name.slice(9))) {
        await readPrivate(join(directory, name), 8 * 1024 * 1024); await rm(join(directory, name));
      }
      state = { schema: SCHEMA, datasetDirectory, createdAt: stamp(), revision: 1,
        selectedDraftId: null, selection: null, candidates: [], buyers: [], removedCandidateIds: [], removedBuyerIds: [], workbookSources: [], removedWorkbookIds: [] };
      await atomicJson(directory, 'workspace.json', state);
    } else state = await readJson(indexPath, 8 * 1024 * 1024);
    if (state.schema !== SCHEMA || state.datasetDirectory !== datasetDirectory || !Number.isSafeInteger(state.revision) ||
        !Array.isArray(state.candidates) || !Array.isArray(state.buyers) || !Array.isArray(state.removedCandidateIds) ||
        !Array.isArray(state.removedBuyerIds) || state.removedCandidateIds.some(id => !UUID.test(id)) ||
        state.removedBuyerIds.some(id => !UUID.test(id)) || new Set(state.candidates.map(c => c.id)).size !== state.candidates.length ||
        new Set(state.buyers.map(item => item.id)).size !== state.buyers.length)
      throw fault('WORKSPACE_BINDING_CHANGED', 'Reopen this workspace against its original dataset state directory.');
    state.candidates.forEach(validateCandidate);
    state.buyers.forEach(validateBuyer);
    for (const path of Object.values(roots)) await privateDirectory(path, true);

    async function save(change) {
      if (closed) throw fault('WORKSPACE_CLOSED');
      const next = copy(state); change(next); next.revision++;
      if (bytes(next).length > 8 * 1024 * 1024)
        throw fault('WORKSPACE_METADATA_CAPACITY', 'Export and remove completed candidate work before saving more history.');
      await atomicJson(directory, 'workspace.json', next); state = next;
